          "title": null
        },
        "y": {
          "value": 95.0
        },
        "text": {
          "value": "40%"
        }
      }
    },
    {
      "transform": [
        {
          "calculate": "datum[''Reminder Group''] == ''Standard reminder'' ? datum[''Pilot No-show Rate''] : null",
          "as": "s"
        },
        {
          "calculate": "datum[''Reminder Group''] == ''Enhanced reminder'' ? datum[''Pilot No-show Rate''] : null",
          "as": "e"
        },
        {
          "aggregate": [
            {
              "op": "max",
              "field": "s",
              "as": "s"
            },
            {
              "op": "max",
              "field": "e",
              "as": "e"
            }
          ]
        },
        {
          "calculate": "(datum.s - datum.e) * 100",
          "as": "pp"
        },
        {
          "calculate": "(datum.s - datum.e) / datum.s",
          "as": "rel"
        },
        {
          "calculate": "''\u2212'' + format(datum.pp, ''.1f'') + '' percentage points \u00b7 \u2212'' + format(datum.rel, ''.1%'') + '' relative''",
          "as": "chip"
        }
      ],
      "layer": [
        {
          "mark": {
            "type": "rect",
            "cornerRadius": 13,
            "color": {
              "x1": 0,
              "y1": 0,
              "x2": 1,
              "y2": 0,
              "gradient": "linear",
              "stops": [
                {
                  "offset": 0,
